# non-captured
try: process_refund_request(mk("authorized"), "1.00", "u", T0)
except BillingError as e: print("state:", e.code)
# non-positive
try: process_refund_request(mk(), "0", "u", T0)
except BillingError as e: print("zero:", e.code)
# already refunded
p = mk(); process_refund_request(p, "100.00", "u", T0)
try: process_refund_request(p, "1.00", "u", T0)
except BillingError as e: print("again:", e.code)
EOF"}

